	// +kubebuilder:validation:Enum=AND;OR;NOT
	Operator string `json:"operator" yaml:"operator"`

	// Conditions is the list of rule references to evaluate
	Conditions []RuleConditionConfig `json:"conditions" yaml:"conditions"`
