36	func (r *SemanticRouterReconciler) isRunningOnOpenShift(ctx context.Context) bool {
37		r.isOpenShiftOnce.Do(func() {
38			logger := log.FromContext(ctx)
39	
40			route := &metav1.PartialObjectMetadata{}
41			route.SetGroupVersionKind(schema.GroupVersionKind{
42				Group:   "route.openshift.io",
43				Version: "v1",
44				Kind:    "Route",
45			})
46	
47			err := r.List(ctx, &metav1.PartialObjectMetadataList{
48				TypeMeta: metav1.TypeMeta{
49					APIVersion: "route.openshift.io/v1",
50					Kind:       "Route",
51				},
52			}, &client.ListOptions{Limit: 1})
53	
54			isOpenShift := err == nil || !meta.IsNoMatchError(err)
55			r.isOpenShift = &isOpenShift
56	
57			if isOpenShift {
58				logger.Info("Detected OpenShift platform - will use OpenShift-compatible security contexts")
59			} else {
60				logger.Info("Detected standard Kubernetes platform - will use standard security contexts")
61			}
62		})
63	
64		if r.isOpenShift != nil {
65			return *r.isOpenShift
66		}
67		return false
68	}
69	
70	func (r *SemanticRouterReconciler) fetchSemanticRouter(ctx context.Context, req ctrl.Request) (*vllmv1alpha1.SemanticRouter, error) {
71		logger := log.FromContext(ctx)
72	
73		semanticrouter := &vllmv1alpha1.SemanticRouter{}
74		err := r.Get(ctx, req.NamespacedName, semanticrouter)
75		if err != nil {
76			if errors.IsNotFound(err) {
77				logger.Info("SemanticRouter resource not found. Ignoring since object must be deleted")
78				return nil, nil
79			}
80			logger.Error(err, "Failed to get SemanticRouter")
81			return nil, err
82		}
83	
84		return semanticrouter, nil
85	}
86	
87	func (r *SemanticRouterReconciler) handleFinalizerFlow(ctx context.Context, semanticrouter *vllmv1alpha1.SemanticRouter) (done bool, err error) {
88		if semanticrouter.DeletionTimestamp.IsZero() {
89			if !controllerutil.ContainsFinalizer(semanticrouter, SemanticRouterFinalizer) {
90				controllerutil.AddFinalizer(semanticrouter, SemanticRouterFinalizer)
91				if err := r.Update(ctx, semanticrouter); err != nil {
92					return false, err
93				}
94			}
95			return false, nil
96		}
97	
98		if !controllerutil.ContainsFinalizer(semanticrouter, SemanticRouterFinalizer) {
99			return true, nil
100		}
101	
102		if err := r.finalizeSemanticRouter(ctx, semanticrouter); err != nil {
103			return false, err
104		}
105	
106		controllerutil.RemoveFinalizer(semanticrouter, SemanticRouterFinalizer)
107		if err := r.Update(ctx, semanticrouter); err != nil {
108			return false, err
109		}
110		return true, nil
111	}
112	
113	func (r *SemanticRouterReconciler) ensureInitialProgressingStatus(
114		ctx context.Context,
115		req ctrl.Request,
116		semanticrouter *vllmv1alpha1.SemanticRouter,
117		logger logr.Logger,
118	) (requeue bool, err error) {
119		if len(semanticrouter.Status.Conditions) != 0 {
120			return false, nil
121		}
122	
123		meta.SetStatusCondition(&semanticrouter.Status.Conditions, metav1.Condition{
124			Type:    typeProgressingSemanticRouter,
125			Status:  metav1.ConditionTrue,
126			Reason:  "Reconciling",
127			Message: "Starting reconciliation",
128		})
129	
130		err = retry.RetryOnConflict(retry.DefaultRetry, func() error {
131			current := &vllmv1alpha1.SemanticRouter{}
132			if err := r.Get(ctx, req.NamespacedName, current); err != nil {
133				return err
134			}
135			meta.SetStatusCondition(&current.Status.Conditions, metav1.Condition{
136				Type:    typeProgressingSemanticRouter,
137				Status:  metav1.ConditionTrue,
138				Reason:  "Reconciling",
139				Message: "Starting reconciliation",
140			})
141			return r.Status().Update(ctx, current)
142		})
143		if err != nil {
144			logger.Error(err, "Failed to update initial SemanticRouter status, will retry on next reconcile")
145		}
146		return true, nil
147	}
148	
149	func (r *SemanticRouterReconciler) reconcileOwnedResources(
150		ctx context.Context,
151		semanticrouter *vllmv1alpha1.SemanticRouter,
152		logger logr.Logger,
153	) error {
154		if err := r.reconcileServiceAccount(ctx, semanticrouter); err != nil {
155			logger.Error(err, "Failed to reconcile ServiceAccount")
156			return err
157		}
158	
159		if err := r.reconcileConfigMap(ctx, semanticrouter); err != nil {
160			logger.Error(err, "Failed to reconcile ConfigMap")
161			return err
162		}
163	
164		if err := r.reconcilePVC(ctx, semanticrouter); err != nil {
165			logger.Error(err, "Failed to reconcile PersistentVolumeClaim")
166			return err
167		}
168	
169		gatewayMode, err := reconcileGatewayIntegration(ctx, r.Client, r.Scheme, semanticrouter)
170		if err != nil {
171			logger.Error(err, "Gateway integration failed")
