11	
12	func (r *SemanticRouterReconciler) applyOperatorConfigSpec(canonical *routerconfig.CanonicalConfig, spec vllmv1alpha1.ConfigSpec) error {
13		if err := r.applyOperatorModelCatalog(canonical, spec); err != nil {
14			return err
15		}
16		if err := r.applyOperatorStoresAndIntegrations(canonical, spec); err != nil {
17			return err
18		}
19		if err := r.applyOperatorProviderDefaults(canonical, spec); err != nil {
20			return err
21		}
22		if err := r.applyOperatorServices(canonical, spec); err != nil {
23			return err
24		}
25		if err := r.applyOperatorRouting(canonical, spec); err != nil {
26			return err
27		}
28		if spec.Strategy != "" {
29			canonical.Global.Router.Strategy = routerconfig.RoutingStrategy(spec.Strategy)
30		}
31		return nil
32	}
33	
34	func (r *SemanticRouterReconciler) applyOperatorModelCatalog(canonical *routerconfig.CanonicalConfig, spec vllmv1alpha1.ConfigSpec) error {
35		if spec.EmbeddingModels != nil {
36			embeddings, err := convertToTypedConfig[routerconfig.EmbeddingModels](r, spec.EmbeddingModels)
37			if err != nil {
38				return fmt.Errorf("config.embedding_models: %w", err)
39			}
40			canonical.Global.ModelCatalog.Embeddings.Semantic = embeddings
41		}
42	
43		if spec.PromptGuard != nil {
44			promptGuard, err := convertToTypedConfig[routerconfig.CanonicalPromptGuardModule](r, spec.PromptGuard)
45			if err != nil {
46				return fmt.Errorf("config.prompt_guard: %w", err)
47			}
48			canonical.Global.ModelCatalog.Modules.PromptGuard = promptGuard
49		}
50	
51		if spec.Classifier != nil {
52			classifier, err := r.convertClassifierModule(spec.Classifier)
53			if err != nil {
54				return fmt.Errorf("config.classifier: %w", err)
55			}
56			canonical.Global.ModelCatalog.Modules.Classifier = classifier
57		}
58		return nil
59	}
60	
61	func (r *SemanticRouterReconciler) applyOperatorStoresAndIntegrations(canonical *routerconfig.CanonicalConfig, spec vllmv1alpha1.ConfigSpec) error {
62		if spec.SemanticCache != nil {
63			semanticCache, err := convertToTypedConfig[routerconfig.SemanticCache](r, spec.SemanticCache)
64			if err != nil {
65				return fmt.Errorf("config.semantic_cache: %w", err)
66			}
67			canonical.Global.Stores.SemanticCache = semanticCache
68		}
69		if spec.Tools != nil {
70			tools, err := convertToTypedConfig[routerconfig.ToolsConfig](r, spec.Tools)
71			if err != nil {
72				return fmt.Errorf("config.tools: %w", err)
73			}
74			canonical.Global.Integrations.Tools = tools
75		}
76		return nil
77	}
78	
79	func (r *SemanticRouterReconciler) applyOperatorProviderDefaults(canonical *routerconfig.CanonicalConfig, spec vllmv1alpha1.ConfigSpec) error {
80		if spec.ReasoningFamilies != nil {
81			canonical.Providers.Defaults.ReasoningFamilies = convertReasoningFamilies(spec.ReasoningFamilies)
82		}
83		if spec.DefaultReasoningEffort != "" {
84			canonical.Providers.Defaults.DefaultReasoningEffort = spec.DefaultReasoningEffort
85		}
86		return nil
87	}
88	
89	func (r *SemanticRouterReconciler) applyOperatorServices(canonical *routerconfig.CanonicalConfig, spec vllmv1alpha1.ConfigSpec) error {
90		if spec.API != nil {
91			api, err := convertToTypedConfig[routerconfig.APIConfig](r, spec.API)
92			if err != nil {
93				return fmt.Errorf("config.api: %w", err)
94			}
95			canonical.Global.Services.API = api
96		}
97		if spec.Observability != nil {
98			observability, err := convertToTypedConfig[routerconfig.ObservabilityConfig](r, spec.Observability)
99			if err != nil {
100				return fmt.Errorf("config.observability: %w", err)
101			}
102			canonical.Global.Services.Observability = observability
103		}
104		return nil
105	}
106	
107	func (r *SemanticRouterReconciler) applyOperatorRouting(canonical *routerconfig.CanonicalConfig, spec vllmv1alpha1.ConfigSpec) error {
108		if spec.Routing != nil {
109			routing, fields, err := canonicalRoutingFromKubernetesJSON(spec.Routing)
110			if err != nil {
111				return formatCanonicalRoutingOverrideError(err)
112			}
113			applyCanonicalRoutingOverrides(canonical, routing, fields)
114		}
115		if len(spec.ComplexityRules) > 0 {
116			complexity, err := r.convertComplexityRules(spec.ComplexityRules)
117			if err != nil {
118				return fmt.Errorf("config.complexity_rules: %w", err)
119			}
120			canonical.Routing.Signals.Complexity = complexity
121		}
122		if len(spec.Decisions) > 0 {
123			decisions, err := convertToTypedConfig[[]routerconfig.Decision](r, spec.Decisions)
124			if err != nil {
125				return fmt.Errorf("config.decisions: %w", err)
126			}
127			canonical.Routing.Decisions = decisions
128		}
129		return nil
130	}
131	
132	func (r *SemanticRouterReconciler) convertClassifierModule(spec *vllmv1alpha1.ClassifierConfig) (routerconfig.CanonicalClassifierModule, error) {
133		if spec == nil {
134			return routerconfig.CanonicalClassifierModule{}, nil
135		}
136	
137		var classifier routerconfig.CanonicalClassifierModule
138	
139		if spec.CategoryModel != nil {
140			domain, err := convertToTypedConfig[routerconfig.CanonicalCategoryModule](r, spec.CategoryModel)
141			if err != nil {
142				return routerconfig.CanonicalClassifierModule{}, fmt.Errorf("domain: %w", err)
143			}
144			classifier.Domain = domain
145		}
146	
147		if spec.PIIModel != nil {
148			pii, err := convertToTypedConfig[routerconfig.CanonicalPIIModule](r, spec.PIIModel)
149			if err != nil {
150				return routerconfig.CanonicalClassifierModule{}, fmt.Errorf("pii: %w", err)
151			}
152			classifier.PII = pii
153		}
154	
155		return classifier, nil
156	}
157	
158	func (r *SemanticRouterReconciler) convertComplexityRules(spec []vllmv1alpha1.ComplexityRulesConfig) ([]routerconfig.ComplexityRule, error) {
159		rules := make([]routerconfig.ComplexityRule, 0, len(spec))
160		for _, entry := range spec {
161			rule, err := convertToTypedConfig[routerconfig.ComplexityRule](r, entry)
162			if err != nil {
163				return nil, fmt.Errorf("%s: %w", entry.Name, err)
164			}
165			if entry.Composer != nil {
166				rule.Composer = &routerconfig.RuleCombination{
167					Operator:   entry.Composer.Operator,
168					Conditions: convertCompositionConditions(entry.Composer.Conditions),
169				}
170			}
