40	func (r *SemanticRouterReconciler) reconcileServiceAccount(ctx context.Context, sr *vllmv1alpha1.SemanticRouter) error {
41		if sr.Spec.ServiceAccount.Create == nil || !*sr.Spec.ServiceAccount.Create {
42			return nil
43		}
44	
45		saName := sr.Spec.ServiceAccount.Name
46		if saName == "" {
47			saName = sr.Name
48		}
49	
50		sa := &corev1.ServiceAccount{
51			ObjectMeta: metav1.ObjectMeta{
52				Name:        saName,
53				Namespace:   sr.Namespace,
54				Annotations: sr.Spec.ServiceAccount.Annotations,
55			},
56		}
57	
58		if err := controllerutil.SetControllerReference(sr, sa, r.Scheme); err != nil {
59			return err
60		}
61	
62		found := &corev1.ServiceAccount{}
63		err := r.Get(ctx, types.NamespacedName{Name: sa.Name, Namespace: sa.Namespace}, found)
64		if err != nil && errors.IsNotFound(err) {
65			return r.Create(ctx, sa)
66		} else if err != nil {
67			return err
68		}
69	
70		if !reflect.DeepEqual(found.Annotations, sa.Annotations) {
71			found.Annotations = sa.Annotations
72			return r.Update(ctx, found)
73		}
74	
75		return nil
76	}
77	
78	func (r *SemanticRouterReconciler) reconcilePVC(ctx context.Context, sr *vllmv1alpha1.SemanticRouter) error {
79		if sr.Spec.Persistence.Enabled == nil || !*sr.Spec.Persistence.Enabled {
80			return nil
81		}
82	
83		if sr.Spec.Persistence.ExistingClaim != "" {
84			return nil
85		}
86	
87		validatedStorageClass, err := validateStorageClass(ctx, r.Client, sr.Spec.Persistence.StorageClassName)
88		if err != nil {
89			return fmt.Errorf("StorageClass validation failed: %w", err)
90		}
91	
92		sr.Spec.Persistence.StorageClassName = validatedStorageClass
93	
94		pvc, err := r.generatePVC(sr)
95		if err != nil {
96			return fmt.Errorf("failed to generate PVC: %w", err)
97		}
98		if err := controllerutil.SetControllerReference(sr, pvc, r.Scheme); err != nil {
99			return err
100		}
101	
102		found := &corev1.PersistentVolumeClaim{}
103		err = r.Get(ctx, types.NamespacedName{Name: pvc.Name, Namespace: pvc.Namespace}, found)
104		if err != nil && errors.IsNotFound(err) {
105			return r.Create(ctx, pvc)
106		}
107	
108		return err
109	}
110	
111	func (r *SemanticRouterReconciler) reconcileDeployment(ctx context.Context, sr *vllmv1alpha1.SemanticRouter, gatewayMode string) error {
112		deployment := r.generateDeployment(sr, gatewayMode)
113		if err := controllerutil.SetControllerReference(sr, deployment, r.Scheme); err != nil {
114			return err
115		}
116	
117		found := &appsv1.Deployment{}
118		err := r.Get(ctx, types.NamespacedName{Name: deployment.Name, Namespace: deployment.Namespace}, found)
119		if err != nil && errors.IsNotFound(err) {
120			return r.Create(ctx, deployment)
121		} else if err != nil {
122			return err
123		}
124	
125		if !reflect.DeepEqual(found.Spec, deployment.Spec) {
126			return retry.RetryOnConflict(retry.DefaultRetry, func() error {
127				if err := r.Get(ctx, types.NamespacedName{Name: deployment.Name, Namespace: deployment.Namespace}, found); err != nil {
128					return err
129				}
130				found.Spec = deployment.Spec
131				return r.Update(ctx, found)
132			})
133		}
134	
135		return nil
136	}
137	
138	func (r *SemanticRouterReconciler) reconcileService(ctx context.Context, sr *vllmv1alpha1.SemanticRouter, gatewayMode string) error {
139		svc := r.generateService(sr, gatewayMode)
140		if err := controllerutil.SetControllerReference(sr, svc, r.Scheme); err != nil {
141			return err
142		}
143	
144		found := &corev1.Service{}
