36	func (r *SemanticRouterReconciler) reconcileConfigMap(ctx context.Context, sr *vllmv1alpha1.SemanticRouter) error {
37		if err := validateSemanticCacheConfig(sr.Spec.Config.SemanticCache); err != nil {
38			return fmt.Errorf("invalid semantic cache configuration: %w", err)
39		}
40	
41		if err := r.resolveSemanticCacheSecrets(ctx, sr); err != nil {
42			return fmt.Errorf("failed to resolve cache secrets: %w", err)
43		}
44	
45		configData, err := r.generateConfigYAML(ctx, sr)
46		if err != nil {
47			return err
48		}
49	
50		toolsData, err := r.generateToolsJSON(sr)
51		if err != nil {
52			return err
53		}
54	
55		cm := &corev1.ConfigMap{
56			ObjectMeta: metav1.ObjectMeta{
57				Name:      sr.Name + "-config",
58				Namespace: sr.Namespace,
59			},
60			Data: map[string]string{
61				"config.yaml":   configData,
62				"tools_db.json": toolsData,
63			},
64		}
65	
66		if err := controllerutil.SetControllerReference(sr, cm, r.Scheme); err != nil {
67			return err
68		}
69	
70		found := &corev1.ConfigMap{}
71		err = r.Get(ctx, types.NamespacedName{Name: cm.Name, Namespace: cm.Namespace}, found)
72		if err != nil && errors.IsNotFound(err) {
73			return r.Create(ctx, cm)
74		} else if err != nil {
75			return err
76		}
77	
78		if !reflect.DeepEqual(found.Data, cm.Data) {
79			return retry.RetryOnConflict(retry.DefaultRetry, func() error {
80				if err := r.Get(ctx, types.NamespacedName{Name: cm.Name, Namespace: cm.Namespace}, found); err != nil {
81					return err
82				}
83				found.Data = cm.Data
84				return r.Update(ctx, found)
85			})
86		}
87	
88		return nil
89	}
90	
91	func (r *SemanticRouterReconciler) generateConfigYAML(ctx context.Context, sr *vllmv1alpha1.SemanticRouter) (string, error) {
92		config, err := r.buildCanonicalConfig(ctx, sr)
93		if err != nil {
94			return "", err
95		}
96	
97		data, err := yaml.Marshal(config)
98		if err != nil {
99			return "", err
100		}
101	
102		return string(data), nil
103	}
104	
105	func (r *SemanticRouterReconciler) generateToolsJSON(sr *vllmv1alpha1.SemanticRouter) (string, error) {
106		if sr.Spec.ToolsDb == nil {
107			return "[]", nil
108		}
109	
110		data, err := json.Marshal(sr.Spec.ToolsDb)
111		if err != nil {
112			return "", err
113		}
114	
115		return string(data), nil
116	}
