40	// parseQuantity parses a quantity string (e.g., "1Gi", "500Mi")
41	func (r *SemanticRouterReconciler) parseQuantity(s string) (resource.Quantity, error) {
42		return resource.ParseQuantity(s)
43	}
44	
45	// convertToConfigMap converts JSON-tagged config structs into YAML-ready maps or
46	// slices, coercing numeric-looking strings into numbers for the router runtime.
47	func (r *SemanticRouterReconciler) convertToConfigMap(v interface{}) interface{} {
48		// Marshal to JSON first (which respects json struct tags), then unmarshal to map[string]interface{}
49		// This preserves the JSON tag field names (snake_case) and structure
50		data, err := json.Marshal(v)
51		if err != nil {
52			return v
53		}
54	
55		var result interface{}
56		if err := json.Unmarshal(data, &result); err != nil {
57			return v
58		}
59	
60		return r.normalizeConfigValue(result)
61	}
62	
63	// convertStringsToFloats recursively converts string values to appropriate types
64	// This handles the mismatch between Kubernetes CRD string fields (to avoid float precision issues)
65	// and the semantic router app's expectation of actual numeric types in YAML
66	func (r *SemanticRouterReconciler) convertStringsToFloats(m map[string]interface{}) {
67		for k, v := range m {
68			m[k] = r.normalizeConfigValue(v)
69		}
70	}
71	
72	func (r *SemanticRouterReconciler) normalizeConfigValue(v interface{}) interface{} {
73		switch val := v.(type) {
74		case string:
75			return r.convertStringValue(val)
76		case map[string]interface{}:
77			r.convertStringsToFloats(val)
78			return val
79		case []interface{}:
80			for i, item := range val {
81				val[i] = r.normalizeConfigValue(item)
82			}
83			return val
84		default:
85			return v
86		}
87	}
88	
89	// convertStringValue attempts to convert a string to the most appropriate type
90	func (r *SemanticRouterReconciler) convertStringValue(s string) interface{} {
91		// Empty string stays as empty string
92		if s == "" {
93			return s
94		}
95	
96		// Try to parse as integer first (for values like "100", "5", etc.)
97		if intVal, err := strconv.ParseInt(s, 10, 64); err == nil {
98			// Check if the string representation matches (no decimal point)
99			if strconv.FormatInt(intVal, 10) == s {
100				return intVal
101			}
102		}
103	
104		// Try to parse as float (for values like "0.6", "1.0", "0.8", etc.)
105		if floatVal, err := strconv.ParseFloat(s, 64); err == nil {
106			return floatVal
107		}
108	
109		// Try to parse as bool (for values like "true", "false")
110		if boolVal, err := strconv.ParseBool(s); err == nil {
111			return boolVal
112		}
113	
114		// If none of the above, keep as string
115		return s
116	}
