118	// getSecretValue retrieves a value from a Kubernetes Secret
119	func (r *SemanticRouterReconciler) getSecretValue(
120		ctx context.Context,
121		namespace string,
122		selector *corev1.SecretKeySelector,
123	) (string, error) {
124		if selector == nil {
125			return "", fmt.Errorf("secret selector is nil")
126		}
127	
128		secret := &corev1.Secret{}
129		err := r.Get(ctx, types.NamespacedName{
130			Name:      selector.Name,
131			Namespace: namespace,
132		}, secret)
133		if err != nil {
134			return "", fmt.Errorf("failed to get secret %s: %w", selector.Name, err)
135		}
136	
137		value, ok := secret.Data[selector.Key]
138		if !ok {
139			return "", fmt.Errorf("key %s not found in secret %s", selector.Key, selector.Name)
140		}
141	
142		return string(value), nil
143	}
