165			}
166			cache.Redis.Connection.Password = password
167			// Clear the SecretRef after resolution so it doesn't appear in the ConfigMap
168			cache.Redis.Connection.PasswordSecretRef = nil
169		}
170	
171		// Resolve Valkey password from Secret
172		if cache.Valkey != nil && cache.Valkey.Connection.PasswordSecretRef != nil {
173			password, err := r.getSecretValue(
174				ctx,
175				sr.Namespace,
176				cache.Valkey.Connection.PasswordSecretRef,
177			)
178			if err != nil {
179				return fmt.Errorf("failed to resolve Valkey password: %w", err)
180			}
181			cache.Valkey.Connection.Password = password
182			// Clear the SecretRef after resolution so it doesn't appear in the ConfigMap
183			cache.Valkey.Connection.PasswordSecretRef = nil
184		}
185	
186		// Resolve Milvus password from Secret
187		if cache.Milvus != nil &&
188			cache.Milvus.Connection.Auth.PasswordSecretRef != nil {
