196			}
197			cache.Milvus.Connection.Auth.Password = password
198			// Clear the SecretRef after resolution so it doesn't appear in the ConfigMap
199			cache.Milvus.Connection.Auth.PasswordSecretRef = nil
200		}
201	
202		return nil
203	}
