205	// validateSemanticCacheConfig validates cache configuration consistency
206	func validateSemanticCacheConfig(cache *vllmv1alpha1.SemanticCacheConfig) error {
207		if cache == nil || !cache.Enabled {
208			return nil
209		}
210	
211		switch cache.BackendType {
